-- S0-05: tables owned by the Investigation context (schema `investigation`), per the Engineering Owner's decisions
-- Q2 to Q10 (docs/specs/S0-05-owner-approval.md): UUT, TestAttempt, InvestigationCase and CaseTestAttemptLink.
-- Ids are SDRIS internal UUIDv7 values generated by the application. Timestamps are SDRIS record creation or
-- registration instants (timestamptz), generated by PostgreSQL (default now()) and never supplied by the application,
-- and are not external execution times. Equal timestamps are allowed: ordering adds deterministic keys.
-- No uniqueness on serial number, hostname or external execution reference, no content checks on text, no status
-- or lifecycle columns: none are approved.

create table investigation.uut (
  id            uuid        primary key,
  serial_number text,
  hostname      text,
  created_at    timestamptz not null default now()
);

create table investigation.test_attempt (
  id                           uuid        primary key,
  uut_id                       uuid        not null references investigation.uut (id),
  -- controlled vocabulary (Q4); extending it needs an explicit vocabulary change and a migration
  stage                        text        not null check (stage in ('IST', 'SAT')),
  external_execution_reference text,
  registered_at                timestamptz not null default now(),
  -- lets a link prove that the attempt belongs to the same UUT as the case
  constraint test_attempt_id_uut_key unique (id, uut_id)
);

create table investigation.investigation_case (
  id          uuid        primary key,
  uut_id      uuid        not null references investigation.uut (id),
  opened_at   timestamptz not null default now(),
  -- optimistic concurrency: every successful save increments it
  version     integer     not null default 1 check (version >= 1),
  -- lets child rows prove they belong to this case AND this UUT
  constraint investigation_case_id_uut_key unique (id, uut_id)
);

create table investigation.case_test_attempt_link (
  case_id     uuid        not null,
  attempt_id  uuid        not null,
  uut_id      uuid        not null,
  role        text        not null check (role in ('INITIAL_FAILURE', 'RETEST', 'SUPPORTING', 'CONTEXT')),
  linked_at   timestamptz not null default now(),
  primary key (case_id, attempt_id, role),
  -- Cross-UUT linking is rejected by the database as well as by the domain: the one uut_id stored on the link
  -- must be the UUT of the case AND the UUT of the attempt.
  constraint case_test_attempt_link_case_uut_fkey
    foreign key (case_id, uut_id) references investigation.investigation_case (id, uut_id),
  constraint case_test_attempt_link_attempt_uut_fkey
    foreign key (attempt_id, uut_id) references investigation.test_attempt (id, uut_id)
);

-- UUT, TestAttempt and link rows are immutable after creation in S0-05 (Q4, Q5, Q6).
create function investigation.reject_update() returns trigger language plpgsql as $$
begin
  raise exception '% rows are immutable', tg_table_name using errcode = 'restrict_violation';
end
$$;

create trigger uut_immutable before update on investigation.uut
  for each row execute function investigation.reject_update();
create trigger test_attempt_immutable before update on investigation.test_attempt
  for each row execute function investigation.reject_update();
create trigger case_test_attempt_link_immutable before update on investigation.case_test_attempt_link
  for each row execute function investigation.reject_update();

comment on table investigation.uut is 'Owner: Investigation context (S0-05). Immutable after creation.';
comment on table investigation.test_attempt is 'Owner: Investigation context. Immutable after registration.';
comment on table investigation.investigation_case is 'Owner: Investigation context. Aggregate root; owns its links.';
comment on table investigation.case_test_attempt_link is 'Owner: Investigation context. Part of the InvestigationCase aggregate; immutable.';
